package secpipe.generated;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import org.junit.jupiter.api.Test;

class LoginServletSqliSecurityTest {

    @Test
    void loginRejectsPayload() throws Exception {
        HttpResponse<String> r = HttpClient.newHttpClient().send(
                HttpRequest.newBuilder(URI.create("http://localhost:8080/login?username=%27%20OR%20%271%27%3D%271")).build(),
                HttpResponse.BodyHandlers.ofString());
        assertEquals(401, r.statusCode());
    }
}

package secpipe.generated;

import static org.junit.jupiter.api.Assertions.assertFalse;

import com.shop.app.LoginServlet;
import java.lang.reflect.Proxy;
import java.sql.Connection;
import java.sql.Driver;
import java.sql.DriverManager;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.List;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import org.junit.jupiter.api.Test;

class LoginServletSqliSecurityTest {

    private final List<String> executed = new ArrayList<>();

    @SuppressWarnings("unchecked")
    private <T> T stub(Class<T> type, java.lang.reflect.InvocationHandler h) {
        return (T) Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[] {type}, h);
    }

    @Test
    void usernamePayloadMustNotReachTheQueryText() throws Exception {
        String payload = "' OR '1'='1";
        ResultSet rs = stub(ResultSet.class, (p, m, a) -> m.getName().equals("next") ? false : null);
        Statement st = stub(Statement.class, (p, m, a) -> {
            if (m.getName().equals("executeQuery")) {
                executed.add((String) a[0]);
                return rs;
            }
            return null;
        });
        Connection conn = stub(Connection.class, (p, m, a) -> m.getName().equals("createStatement") ? st : null);
        Driver driver = stub(Driver.class, (p, m, a) -> switch (m.getName()) {
            case "acceptsURL" -> true;
            case "connect" -> conn;
            default -> null;
        });
        DriverManager.registerDriver(driver);
        HttpServletRequest req = stub(HttpServletRequest.class,
                (p, m, a) -> m.getName().equals("getParameter") ? payload : null);
        HttpServletResponse resp = stub(HttpServletResponse.class, (p, m, a) -> null);
        try {
            new LoginServlet() { { doPost(req, resp); } };
        } finally {
            DriverManager.deregisterDriver(driver);
        }
        assertFalse(executed.stream().anyMatch(q -> q.contains(payload)),
                "attacker-controlled username reached the SQL text: " + executed);
    }
}
